/* From Uiverse.io by mrhyddenn - Tags: button */
.__UIV_SCOPE__ button {
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 10px 30px;
  transition: 0.5s;
  position: relative;
  font-size: 17px;
  background: #333;
  border: none;
  color: #fff;
}

.__UIV_SCOPE__ button:hover {
  letter-spacing: 0.25em;
  background: #ff1867;
  color: #ff1867;
  box-shadow: 0 0 45px #ff1867;
}

.__UIV_SCOPE__ button::before {
  content: '';
  position: absolute;
  inset: 2px;
  background: #222222;
}

.__UIV_SCOPE__ button span {
  position: relative;
  z-index: 1;
}

.__UIV_SCOPE__ button i {
  position: absolute;
  inset: 0;
  display: block;
}

.__UIV_SCOPE__ button i::before {
  content: '';
  position: absolute;
  border: 2px solid #ff1867;
  width: 7px;
  height: 4px;
  top: -3.5px;
  left: 80%;
  background: #222222;
  transform: translateX(-50%);
  transition: 0.5s;
}

.__UIV_SCOPE__ button:hover i::before {
  width: 20px;
  left: 20%;
}

.__UIV_SCOPE__ button i::after {
  content: '';
  position: absolute;
  border: 2px solid #ff1867;
  width: 7px;
  height: 4px;
  bottom: -3.5px;
  left: 20%;
  background: #222222;
  transform: translateX(-50%);
  transition: 0.5s;
}

.__UIV_SCOPE__ button:hover i::after {
  width: 20px;
  left: 80%;
}
